import * as React from "react";
import { graphql, Link, type HeadFC, type PageProps } from "gatsby";
import { useTranslation } from "react-i18next";
import { useI18next } from "gatsby-plugin-react-i18next";

type PortfolioProject = {
  title: string;
  href?: string;
  role: string;
  stack: string;
  year?: string;
  highlights: string[];
  note?: string;
};

function cn(...xs: Array<string | false | null | undefined>) {
  return xs.filter(Boolean).join(" ");
}

function Section({
  id,
  title,
  subtitle,
  children,
}: {
  id: string;
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <section id={id} className="w-full py-14">
      <div className="w-full px-4 sm:px-8 lg:px-12">
        <header className="mb-8">
          <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight text-accent">{title}</h2>
          {subtitle ? <p className="mt-2 text-base text-neutral max-w-4xl">{subtitle}</p> : null}
        </header>
        {children}
      </div>
    </section>
  );
}

function Card({ children }: { children: React.ReactNode }) {
  return (
    <div className="rounded-2xl border border-neutral/20 bg-secondary p-6 shadow-sm">
      {children}
    </div>
  );
}

function Pill({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-1 text-xs font-medium text-accent">
      {children}
    </span>
  );
}

function BulletList({ items }: { items: string[] }) {
  return (
    <ul className="mt-4 space-y-2 text-sm text-accent">
      {items.map((h) => (
        <li key={h} className="flex gap-2">
          <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
          <span className="min-w-0">{h}</span>
        </li>
      ))}
    </ul>
  );
}

function ProjectCard({
  project,
  openLabel,
}: {
  project: PortfolioProject;
  openLabel: string;
}) {
  const hasLink = Boolean(project.href);

  const content = (
    <Card>
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <h3 className="text-lg font-semibold leading-snug text-accent">{project.title}</h3>
          <p className="mt-1 text-sm text-neutral">
            <span className="font-medium text-accent">{project.role}</span>
            {" · "}
            <span>{project.stack}</span>
            {project.year ? <span>{" · "}{project.year}</span> : null}
          </p>
        </div>

        {hasLink ? (
          <span className="shrink-0 inline-flex items-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent hover:bg-primary/70">
            {openLabel}
          </span>
        ) : null}
      </div>

      <BulletList items={project.highlights} />

      {project.note ? <p className="mt-4 text-sm text-neutral">{project.note}</p> : null}
    </Card>
  );

  return hasLink ? (
    <a
      href={project.href}
      target="_blank"
      rel="noreferrer"
      className="block focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 rounded-2xl"
      aria-label={`${openLabel}: ${project.title}`}
    >
      {content}
    </a>
  ) : (
    content
  );
}

