export const query = graphql`
  query IndexPageQuery($language: String!) {
    locales: allLocale(filter: { language: { eq: $language }, ns: { in: ["index"] } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
